START, EXIT = (3, 1), (1, 4)
BLOCKED = {(2, 2), (2, 4)}


def verify(route):
    """Return None if valid, otherwise describe the first failure."""
    if not route:
        return 'Empty route'
    if route[0] != START:
        return 'Wrong start'

    for i, cell in enumerate(route):
        row, col = cell
        if not (1 <= row <= 3 and 1 <= col <= 4):
            return f'Cell {i} out of bounds: {cell}'
        if cell in BLOCKED:
            return f'Cell {i} is blocked: {cell}'
        if i:
            prev = route[i - 1]
            if abs(row - prev[0]) + abs(col - prev[1]) != 1:
                return f'Non-orthogonal move: {prev} -> {cell}'
            if prev == (1, 3) and cell == (1, 2):
                return f'Reverse gate crossing: {prev} -> {cell}'

    if route[-1] != EXIT:
        return 'Wrong exit'
    return None


def test_verify():
    assert verify([(3, 1), (2, 1), (1, 1), (1, 2),
                   (1, 3), (1, 4)]) is None
    assert verify([(3, 1), (2, 1), (1, 2), (1, 3),
                   (1, 4)]).startswith('Non-orthogonal move')
    assert verify([(3, 1), (3, 2), (3, 3), (2, 3),
                   (1, 3), (1, 2)]).startswith('Reverse gate crossing')
    assert verify([(3, 1), (3, 2), (2, 2)]).startswith('Cell 2 is blocked')


if __name__ == '__main__':
    test_verify()
```

The verifier checks cells and moves in route order; it checks the exit after the route itself. It assumes each cell is a pair of numeric coordinates.

